## solutions

#### iterative

```cpp
#include <string>
#include <vector>
#include <stack>

std::vector<std::string> depthFirstValues(Node* root) {
  std::vector<std::string> values;
  std::stack<Node*> stack;
  if (root != nullptr) {
    stack.push(root);
  }
  while (stack.size()) {
    Node* current = stack.top();
    stack.pop();
    values.push_back(current->val);
    if (current->right != nullptr) {
      stack.push(current->right);
    }
    if (current->left != nullptr) {
      stack.push(current->left);
    }
  }
  return values;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)



#### recursive

```cpp
#include <string>
#include <vector>

void depthFirstValues(Node* root, std::vector<std::string> &values) {
  if (root == nullptr) {
    return;
  }
  values.push_back(root->val);
  depthFirstValues(root->left, values);
  depthFirstValues(root->right, values);
}

std::vector<std::string> depthFirstValues(Node* root) {
  std::vector<std::string> values;
  depthFirstValues(root, values);
  return values;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
